namespace CmsEventProcessor.Infrastructure.Persistence.Models;

/// <summary>
/// Stores one current content snapshot; the SQL row version is independent of the CMS source revision.
/// </summary>
internal sealed class SnapshotRow
{
    public string Id { get; set; } = string.Empty;
    public string Payload { get; set; } = string.Empty;
    public long Version { get; set; }
    public DateTimeOffset CmsTimestamp { get; set; }
    public bool CmsPublished { get; set; }
    public bool AdminDisabled { get; set; }

    /// <summary>
    /// Is generated by SQL Server for optimistic concurrency and must never be interpreted as the CMS version.
    /// </summary>
    public byte[] RowVersion { get; set; } = [];
}
